// Hand-written `mongoose` stub for the flowatlas fixture suite. It declares only what
// `fixtures/nest-mongoose/src` touches, shaped like the real library so that
// `resolveTypeOrigin` sees the same thing it sees on a real repo: the receiver's type
// is declared in `node_modules/mongoose`, and the document type is the first type
// argument of `Model<Doc>`.
//
// A model carries two facts at once, which is why this fixture exists beside the
// `typeorm` one: the type argument names the document, exactly as `Repository<Order>`
// does, while the collection is the string the model was declared with and is in no
// type at all. The `mongoose` descriptor takes the first from the types and the second
// from the declaration the receiver names.

export declare class Schema<T> {
  constructor(definition: Record<string, unknown>);
}

export declare class Document<T> {
  save(): Promise<T>;
}

/**
 * What a query method actually hands back, and the reason this is not a `Promise`.
 *
 * A `Query` is a builder that happens to be thenable: it carries `then`, so it
 * can be awaited and returned from an `async` function, and it is not a
 * `Promise`, so it can go on being narrowed with `.where(...)`, `.lean()` or
 * `.exec()` first. The stub declared `Promise` here for a long while, which is
 * a different kind of type rather than a smaller one, and a data layer that
 * ever started reading the return instead of the receiver would have been
 * reading a shape that no real mongoose repository produces.
 */
export declare class Query<ResultType, DocType> {
  exec(): Promise<ResultType>;
  lean(): Query<ResultType, DocType>;
  then: Promise<ResultType>['then'];
  catch: Promise<ResultType>['catch'];
  finally: Promise<ResultType>['finally'];
}

export interface Model<T> {
  new (doc: Partial<T>): Document<T>;
  find(filter?: unknown): Query<T[], T>;
  findById(id: string): Query<T | null, T>;
  countDocuments(filter?: unknown): Query<number, T>;
  create(doc: Partial<T>): Promise<T>;
  updateOne(filter: unknown, update: unknown): Query<unknown, T>;
  deleteOne(filter: unknown): Query<unknown, T>;
}

export declare const model: <T>(collection: string, schema: Schema<T>) => Model<T>;

/** Every model the connection knows, by name. Real, and unreadable on purpose. */
export declare const models: Record<string, Model<unknown>>;
